import React from 'react';
import { motion } from 'motion/react';
import { PolicyPageShell } from '../components/ui/PolicyPageShell';
import type { PolicySection } from '../components/ui/PolicyPageShell';
import { useLanguage } from '../lib/LanguageContext';

type Section = { title: string; body?: string; paragraphs?: string[] };

const sections: Record<'en' | 'id', Section[]> = {
  en: [
    { title: 'Purpose and scope', body: 'This Privacy Policy explains how PT Kapitech Digital Indonesia (“Kapitech”, “we”, “us”, or “our”) handles Personal Data in connection with kapitech.id and website-related interactions. It covers information submitted through contact, career, vendor, newsletter, consultation, and similar forms, as well as technical and usage information generated when you browse the website.\n\nThe website is a public-facing business and editorial platform. A client project, employee relationship, freelancer engagement, or other service arrangement may involve additional privacy, security, confidentiality, or data-processing terms. When a written agreement applies to a particular processing activity, that agreement may impose more specific or stricter requirements than this general website policy.' },
    { title: 'Definitions', body: 'For this policy, “Personal Data” means information that identifies or can reasonably be associated with an individual, directly or indirectly. “Processing” includes collecting, recording, organising, storing, using, disclosing, transferring, updating, combining, restricting, or deleting information. “Website” refers to kapitech.id and the public website functions operated by Kapitech.\n\n“Controller” refers to the party that determines the purpose and means of processing. “Processor” refers to a party that processes data on behalf of a controller. These roles can vary by context. Kapitech may act as controller for information collected for its own business purposes and may act as processor or service provider when a client contract instructs Kapitech to process data on the client’s behalf.' },
    { title: 'Who controls your Personal Data', body: 'For Personal Data collected through the public website for Kapitech’s own purposes, the controller is PT Kapitech Digital Indonesia. This includes information needed to respond to enquiries, manage business communications, review applications, operate the site, maintain security, and perform other legitimate website and business functions.\n\nIn a client engagement, the responsible party may be different. If a client determines the purpose of processing and asks Kapitech to handle data on the client’s behalf, the client may remain the controller while Kapitech acts as a processor. The applicable proposal, SOW, NDA, DPA, or other project agreement should be used to determine the exact role and responsibilities.' },
    { title: 'Personal Data we may collect', body: 'We collect only information that is relevant to a particular interaction and that you choose or are required to provide. Depending on the form, relationship, or website feature, this can include:', paragraphs: [
      'Identity and contact details, including name, business email, phone number, company, and other contact details you choose to provide. Separate communication channels may collect additional information that you voluntarily send.',
      'Project information, including services of interest, objectives, requirements, timelines, preferred technology, budget range, and the content of your enquiry.',
      'Recruitment information, including role applied for, CV or resume, portfolio URL, cover letter, experience, skills, specialty, tools, references, and related communications.',
      'Vendor or freelance information, including service specialty, experience, tools, portfolio, rate information, availability, and supporting documents.',
      'Communication information, including email messages, form submissions, attachments, feedback, meeting notes, and records of our responses.',
      'Newsletter or marketing preferences, including subscription status and communication preferences.',
      'Technical and security information, including IP address, browser and device characteristics, timestamps, pages visited, referring host, and diagnostic information that may be generated by the website or its infrastructure.',
      'Campaign and attribution information such as UTM parameters and similar identifiers when optional analytics is enabled after consent.',
      'Any other information that you voluntarily provide through an interaction with Kapitech.'
    ]},
    { title: 'Information you should not submit', body: 'Our public website forms are not designed as a secure channel for submitting highly sensitive information unless the relevant form or written agreement specifically requests it. Do not send passwords, private encryption keys, financial account credentials, government secrets, medical records, or other sensitive information that is not necessary for your request.\n\nIf sensitive information is necessary for a contracted project, use the secure method or transfer process agreed with the Kapitech team. We may decline to process information that is excessive, unrelated to the stated purpose, or presents an unreasonable security or legal risk.' },
    { title: 'How we receive Personal Data', paragraphs: [
      'Directly from you when you fill in a website form, send an email, contact us by phone or WhatsApp, subscribe to updates, or otherwise communicate with our team.',
      'From your browser or device when essential technical information is generated while using the website.',
      'From professional or public information you voluntarily make available, such as a portfolio, company website, or professional profile included in an application.',
      'From service providers that operate infrastructure, communications, submissions, analytics, security, hosting, or other systems used by Kapitech, where they process information in connection with our instructions or your interaction.',
      'From clients or authorised representatives who provide Personal Data to us for a contracted purpose.'
    ]},
    { title: 'Purposes of processing', body: 'We use Personal Data for defined business, operational, security, and communication purposes. The same information may support more than one closely related purpose, but we do not intend to collect data merely “just in case”. Typical purposes include:', paragraphs: [
      'Responding to enquiries, consultation requests, proposals, and business communications.',
      'Understanding project requirements and preparing scopes, estimates, schedules, specifications, and pre-contract materials.',
      'Delivering contracted services, managing project communication, administration, approvals, invoices, and records.',
      'Assessing employment, internship, freelance, or vendor applications and communicating with candidates or partners.',
      'Sending requested newsletters, updates, or other communications where you have subscribed or otherwise authorised them.',
      'Operating, maintaining, securing, monitoring, troubleshooting, and improving the website and related infrastructure.',
      'Understanding website usage and campaign performance through optional analytics and attribution after consent.',
      'Detecting fraud, abuse, malicious activity, security events, or violations of our terms.',
      'Complying with legal, regulatory, accounting, tax, dispute-resolution, or record-keeping obligations.'
    ]},
    { title: 'Legal bases for processing', body: 'Kapitech seeks to rely on a valid legal basis for each processing activity as required by applicable law. Depending on the context, the basis may include valid consent; taking steps at an individual’s request before entering into a contract; performing a contract; complying with a legal obligation; protecting vital interests; carrying out a public-interest or public-service function where applicable; or pursuing a legitimate interest after considering the rights and interests of the data subject.\n\nWhere consent is the legal basis, the request for consent should be presented clearly for the relevant purpose and should not be treated as a blanket authorisation for unrelated processing. Withdrawal of consent does not automatically invalidate processing that was lawfully completed before withdrawal and does not prevent processing that has another lawful basis.' },
    { title: 'Contact forms and business enquiries', body: 'Information submitted through the public contact form is used to understand and respond to the request. The current website form can collect your name, email, company, phone number, selected services, budget range, and project message. Kapitech may review the request, route it to the appropriate team member, prepare a proposal or follow-up questions, and keep a business record of the communication.\n\nSubmitting a contact form does not automatically subscribe you to a newsletter or general marketing list. A separate subscription or other appropriate authorisation is used for recurring marketing communications. We may contact you in connection with an active enquiry or project without treating that operational communication as marketing.' },
    { title: 'Project discovery and pre-contract information', body: 'Before a contract is signed, we may receive business information such as product plans, target audiences, technical constraints, desired functionality, existing systems, budget expectations, timelines, and internal decision-making requirements. We use that information to evaluate whether Kapitech is suitable for the request and to prepare commercially relevant materials.\n\nPre-contract information may be sensitive even when it is not legally classified as special-category data. We therefore seek to limit internal access to people who reasonably need the information for sales, discovery, design, engineering, finance, or management activities related to the request.' },
    { title: 'Consultation scheduling, project briefs, and NDA requests', body: 'The consultation flow can collect a preferred meeting date, preferred time, timezone, industry, service interest, project description, and an optional request for NDA or confidential handling before detailed information is exchanged. These fields help Kapitech qualify the request, understand timing, route the inquiry, and determine the appropriate next step. A preferred time submitted through the public website is a scheduling request only and does not automatically reserve a meeting slot unless a separate confirmed booking mechanism is used.\n\nThe consultation flow can also accept a project brief attachment in supported document formats. The brief is uploaded through the public AMS API and private document-storage flow before its reference is associated with the inquiry. The attachment should contain only information reasonably necessary for evaluating the project. Do not upload passwords, private keys, financial credentials, secrets, or unrelated sensitive information. A request for NDA handling is recorded with the inquiry; it does not itself create a signed NDA unless Kapitech and the relevant party complete an applicable NDA or other written confidentiality agreement.' },
    { title: 'Recruitment, freelance, and vendor applications', body: 'Applications can include name, email, phone number, portfolio link, cover letter, resume, position applied for, and related professional information. The freelance/vendor flow can additionally collect specialty, rate information, years of experience, tools or stack, notes, and supporting resume material. Authorised members of recruitment, project, operations, design, engineering, finance, or management teams may review relevant information depending on the opportunity.\n\nWe may keep application information for future opportunities where permitted and useful, but applicants should not assume that an application creates an employment, vendor, or contractor relationship. Please avoid submitting unnecessary sensitive Personal Data. Where a specific recruitment process provides additional privacy instructions, those instructions apply to that process.' },
    { title: 'Newsletter and marketing communications', body: 'Where Kapitech offers a newsletter, project insights, campaign update, or other recurring communication, we use the information necessary to deliver that communication and manage subscription preferences. Marketing messages may contain a mechanism to unsubscribe or update preferences.\n\nAn unsubscribe request should stop the relevant recurring marketing communication, although we may retain a minimal suppression record so that we do not inadvertently re-subscribe an address that has opted out. Operational messages that are necessary to respond to an enquiry, administer a contract, or provide a requested service are not necessarily cancelled by a marketing unsubscribe.' },
    { title: 'Technical, security, and usage information', body: 'When you access the website, technical information can be generated automatically by the browser, hosting environment, content delivery layer, security systems, or application itself. Depending on configuration, this may include IP address, browser family and version, operating system, device characteristics, timestamps, requested pages, referring host, HTTP status information, and diagnostic events.\n\nWe use this information primarily for site delivery, security, reliability, troubleshooting, abuse prevention, aggregate analysis, and service improvement. Technical logs may be retained independently from marketing analytics and may remain necessary even when optional analytics consent is not provided.' },
    { title: 'Cookies, local storage, and consent data', body: 'Kapitech uses browser storage and cookies in accordance with the Cookie Policy. Essential storage may remember language or consent choices so the site can operate consistently. Optional analytics and attribution are intended to initialise only after an accepted analytics consent choice is recorded.\n\nCurrent site-managed storage includes values such as “kapitech_cookie_consent”, “kapitech_lang”, “kapitech_ams_theme”, “kapitech_attribution_v1”, and “kapitech_anonymous_id_v1”. The theme value stores the selected visual preference and is used before the React application mounts. Storage keys, provider integrations, and implementation details may change as the website evolves. The Cookie Policy provides the more specific inventory of browser storage and optional tracking. The Cookie Policy is the more specific document for cookie and storage behaviour.' },
    { title: 'Analytics and attribution', body: 'When optional analytics consent is active, the public-site code can initialise Google Analytics 4 and/or Google Tag Manager when the corresponding production environment configuration is present. The repository does not expose production environment values, so this policy does not represent either provider as permanently active. Depending on configuration, events can include page views, selected interactions, page paths, language, campaign parameters, and referral information. The purpose is to understand website usage and campaign performance, not to use the public website as a commercial data-broker service.\n\nProvider-side processing is also subject to the provider’s current technical configuration and terms. We therefore avoid promising a permanent cookie name, exact retention period, processing country, or provider feature when that detail can change without control by Kapitech.' },
    { title: 'Service providers and processors', body: 'The public website uses Kapitech’s AMS API for lead and submission handling. In production, the public site sends contact, recruitment, vendor, and newsletter submissions to the AMS API at ams.kapitech.id/api. Recruitment resume files can also be uploaded through the public resume-upload endpoint before the application record is submitted. Other infrastructure or provider relationships may change over time; this policy does not name a third-party processor unless the active implementation has been verified. Depending on the service, the provider may process Personal Data on our behalf or as an independent provider subject to its own terms.\n\nWe seek to select providers that are appropriate for the service, limit access to information where practical, and use contractual or technical safeguards appropriate to the nature of the processing. The list of providers can change over time as technology and business needs change.' },
    { title: 'Disclosure to other parties', body: 'We may disclose Personal Data where necessary to operate the business, fulfil a request, perform a contract, comply with law, or protect legitimate rights and systems. Examples may include authorised team members and contractors, infrastructure providers, professional advisers, auditors, payment or financial-service providers, legal authorities, or parties involved in a lawful corporate transaction.\n\nWe do not intend to disclose more information than is reasonably necessary for the relevant purpose. We do not treat a user’s Personal Data as a public resource merely because the information was submitted through the website.' },
    { title: 'Legal requests and protection of rights', body: 'There may be circumstances where Kapitech must disclose information to comply with a subpoena, court order, lawful government request, regulatory requirement, or other legal process. We may also disclose information when reasonably necessary to protect the security, rights, property, or safety of Kapitech, our clients, users, team members, or other persons, subject to applicable law.\n\nWhere legally permitted, we seek to limit the disclosure to the relevant information and preserve confidentiality over information that does not need to be disclosed.' },
    { title: 'Client and project confidentiality', body: 'Information received during a client engagement can be subject to a proposal, SOW, NDA, confidentiality clause, data-processing agreement, security schedule, or other written restriction. Those contractual obligations can be more specific or stricter than this general website policy.\n\nKapitech does not intentionally publish confidential client information simply because it is available internally. Client names, logos, screenshots, technical architecture, project metrics, unpublished product plans, credentials, and other sensitive details should only be made public where Kapitech has an appropriate contractual, consent-based, or other lawful basis.' },
    { title: 'International processing and transfers', body: 'Kapitech and its providers may use infrastructure located outside Indonesia. As a result, Personal Data may be processed, stored, or accessed in another country or jurisdiction where privacy rules may differ from those in Indonesia.\n\nWhere cross-border processing is relevant, we seek to apply reasonable contractual, technical, and organisational safeguards and to follow applicable requirements. The location of processing may change when a provider changes its infrastructure, so this policy does not promise that all data will permanently remain in one country.' },
    { title: 'Data retention', body: 'There is no single retention period that applies to all Personal Data. We consider the original purpose, the type and sensitivity of information, the duration of a business or candidate relationship, legal and accounting requirements, dispute risk, security needs, and operational necessity.\n\nWhen information is no longer required for a legitimate purpose, we seek to delete, destroy, anonymise, de-identify, or otherwise securely dispose of it, subject to lawful retention requirements, backups, audit needs, or other legitimate reasons that may require a controlled retention period.' },
    { title: 'Data accuracy and minimisation', body: 'We aim to keep Personal Data reasonably accurate and relevant to the purpose for which it is processed. You can help by providing information that is current and by notifying us when important details change. We may ask for clarification when submitted information appears incomplete, inconsistent, or necessary for a particular request.\n\nWe also seek to avoid collecting information that is irrelevant to the stated purpose. Where a form offers optional fields, you can generally leave them blank unless the field is necessary to evaluate or deliver your request.' },
    { title: 'Security measures', body: 'We use reasonable technical and organisational controls appropriate to the system and information involved. Depending on the context, these may include encrypted network connections, authentication, role-based access, restricted administrative privileges, secure credential handling, logging, monitoring, backups, software updates, and controlled access to internal systems.\n\nSecurity is a process rather than a guarantee. No internet transmission, software system, cloud platform, device, or storage method can be promised to be completely secure. Users should avoid sending secrets or credentials through ordinary public website forms.' },
    { title: 'Personal Data incidents', body: 'If Kapitech becomes aware of a suspected or confirmed Personal Data incident, we may assess its scope, affected systems, categories of data, likely risks, containment options, and any notification duties that arise under applicable law or contract. Response actions may include restricting access, investigating logs, securing accounts, correcting configuration, restoring systems, contacting affected parties, and documenting remediation.\n\nWhere notification is legally required, we will follow the applicable requirements and statutory timing that apply to the relevant incident. Under Indonesia’s Personal Data Protection Law, a controller can have a written notification obligation for a personal-data protection failure, subject to the law and circumstances in force at the time. A security event does not automatically mean that every user will be affected, so any notification should be based on the facts reasonably established during the incident response.' },
    { title: 'Your data-protection rights', body: 'Subject to applicable law, you may have rights relating to your Personal Data, including the right to receive clear information about processing, access your data, obtain a copy where required, correct or update inaccurate data, request deletion or destruction where permitted, withdraw consent where consent is the legal basis, request termination or restriction of processing in applicable circumstances, object to certain processing or profiling, and exercise other rights available under the relevant legal framework.\n\nThe exact scope of a right can depend on the legal basis, purpose, exceptions, third-party obligations, and other circumstances. We do not treat this policy as expanding a statutory right beyond what applicable law provides.' },
    { title: 'Requests to exercise your rights', body: 'Send a privacy or data-rights request to hello@kapitech.id. Include your name, contact information, the nature of the request, and enough context for us to locate the relevant record. If the request concerns a specific form, project, application, or communication, identify it where possible.\n\nWe may ask for reasonable information to verify your identity before disclosing, changing, or deleting data. This is intended to reduce the risk of sending Personal Data to the wrong person. We will respond within the timeframe and conditions required by applicable law. If a request cannot be completed in full, we will explain the limitation where permitted.' },
    { title: 'Automated decision-making and profiling', body: 'The public website is not intended to make high-impact decisions about people solely through automated processing. Website analytics or attribution may create statistical groupings or behavioural measurements, but these functions are not intended to determine a person’s legal status, employment eligibility, creditworthiness, or access to essential services.\n\nIf a future system introduces a materially different form of automated decision-making or profiling, Kapitech will assess the applicable legal, transparency, security, and governance requirements before relying on that system.' },
    { title: 'Children and age-related considerations', body: 'Kapitech is a professional business and digital-services agency, and the website is primarily designed for businesses, professionals, clients, candidates, vendors, and other adult users. We do not intentionally request unnecessary Personal Data from children through ordinary website forms.\n\nIf a parent, guardian, or other person believes that a child has submitted Personal Data to Kapitech in a manner that should not have occurred, contact hello@kapitech.id with the relevant information so we can assess the situation and take reasonable action consistent with applicable law.' },
    { title: 'Third-party websites and services', body: 'The website may link to third-party websites, social networks, hosted tools, embedded services, or external platforms. Those services can have different privacy policies, cookie practices, security controls, and terms. Clicking or submitting information on a third-party service may move the processing outside Kapitech’s direct control.\n\nWe recommend reviewing the relevant third party’s privacy notice before submitting personal or confidential information. A link from kapitech.id does not by itself mean that Kapitech controls the third party or guarantees its practices.' },
    { title: 'Changes, effective date, and contact', body: 'We may update this Privacy Policy when the website, business operations, technology, processing activities, service providers, or legal requirements change. The current version will be published on this page with an updated effective date. Where a material change requires additional notice under applicable law or contract, we will use a reasonable method to provide that notice.\n\nPT Kapitech Digital Indonesia\nLinea Residence, Block G No. 5, Jl. Melati Loka, Paku Jaya, Serpong Utara, Kota Tangerang Selatan, Banten 15220, Indonesia\nEmail: hello@kapitech.id\nPhone / WhatsApp: +62 877-6995-7062' },
    { title: 'Applicable legal framework', body: 'This policy is intended to be read together with applicable Indonesian requirements concerning Personal Data, electronic systems, and online activity, including Law of the Republic of Indonesia No. 27 of 2022 on Personal Data Protection, Government Regulation No. 71 of 2019 on the Operation of Electronic Systems and Transactions, Law No. 1 of 2024 on the Second Amendment to the Electronic Information and Transactions Law, and, where applicable, the rules governing Private Electronic System Operators under Minister of Communication and Informatics Regulation No. 5 of 2020 as amended. The applicable legal framework depends on the actual activity, role, system, and statutory scope involved; listing a regulation here does not constitute a representation that every provision applies to every interaction.\n\nThis policy is a public website privacy notice and is not a substitute for a project-specific data-processing agreement, security schedule, NDA, employment policy, or other contract where a more specific arrangement applies. Nothing in this page is intended to provide legal advice.' }
  ],
  id: [
    { title: 'Tujuan dan ruang lingkup', body: 'Kebijakan Privasi ini menjelaskan bagaimana PT Kapitech Digital Indonesia (“Kapitech”, “kami”) menangani Data Pribadi sehubungan dengan kapitech.id dan interaksi yang berkaitan dengan website. Cakupannya meliputi data yang dikirim melalui formulir kontak, karier, vendor, newsletter, konsultasi, dan formulir sejenis, serta informasi teknis dan penggunaan yang dihasilkan saat Anda menjelajahi website.\n\nWebsite merupakan platform publik untuk kebutuhan bisnis dan editorial. Proyek klien, hubungan kerja, engagement freelance, atau layanan lain dapat memiliki ketentuan privasi, keamanan, kerahasiaan, atau pemrosesan data tambahan. Jika ada perjanjian tertulis yang mengatur aktivitas pemrosesan tertentu, perjanjian tersebut dapat memiliki aturan yang lebih spesifik atau lebih ketat daripada kebijakan umum ini.' },
    { title: 'Definisi', body: 'Dalam kebijakan ini, “Data Pribadi” berarti informasi yang secara langsung atau tidak langsung dapat mengidentifikasi atau dikaitkan secara wajar dengan seseorang. “Pemrosesan” mencakup pengumpulan, pencatatan, pengorganisasian, penyimpanan, penggunaan, pengungkapan, pemindahan, pembaruan, penggabungan, pembatasan, atau penghapusan data. “Website” berarti kapitech.id dan fungsi publik website yang dioperasikan Kapitech.\n\n“Pengendali” adalah pihak yang menentukan tujuan dan cara pemrosesan. “Prosesor” adalah pihak yang memproses data atas nama pengendali. Peran tersebut dapat berbeda tergantung konteks. Kapitech dapat menjadi pengendali untuk data yang digunakan untuk kepentingan bisnisnya sendiri dan dapat menjadi prosesor atau service provider ketika kontrak klien memerintahkan Kapitech memproses data atas nama klien.' },
    { title: 'Siapa yang mengendalikan Data Pribadi Anda', body: 'Untuk Data Pribadi yang dikumpulkan melalui website publik untuk kepentingan Kapitech sendiri, pengendalinya adalah PT Kapitech Digital Indonesia. Ini mencakup data yang diperlukan untuk menjawab pertanyaan, mengelola komunikasi bisnis, menilai lamaran, mengoperasikan website, menjaga keamanan, dan menjalankan fungsi website serta bisnis yang sah.\n\nDalam engagement klien, pihak yang bertanggung jawab dapat berbeda. Jika klien menentukan tujuan pemrosesan dan meminta Kapitech menangani data atas nama klien, klien dapat tetap menjadi pengendali sedangkan Kapitech bertindak sebagai prosesor. Proposal, SOW, NDA, DPA, atau perjanjian proyek lain menjadi acuan untuk menentukan peran dan tanggung jawab secara spesifik.' },
    { title: 'Data Pribadi yang dapat kami kumpulkan', body: 'Kami mengumpulkan informasi yang relevan dengan interaksi tertentu dan yang Anda pilih atau memang perlu Anda berikan. Tergantung formulir, hubungan, atau fungsi website, data dapat mencakup:', paragraphs: [
      'Identitas dan kontak, termasuk nama, email bisnis, nomor telepon atau WhatsApp, perusahaan, jabatan, dan preferensi komunikasi.',
      'Informasi proyek, termasuk layanan yang diminati, tujuan, kebutuhan, timeline, teknologi yang diinginkan, kisaran anggaran, dan isi permintaan.',
      'Informasi rekrutmen, termasuk posisi, CV atau resume, URL portfolio, cover letter, pengalaman, keahlian, spesialisasi, tools, referensi, dan komunikasi terkait.',
      'Informasi vendor atau freelance, termasuk spesialisasi, pengalaman, tools, portfolio, rate, ketersediaan, dan dokumen pendukung.',
      'Informasi komunikasi, termasuk email, pengiriman formulir, lampiran, feedback, catatan meeting, dan catatan respons kami.',
      'Informasi newsletter atau preferensi marketing, termasuk status subscription dan preferensi komunikasi.',
      'Informasi teknis dan keamanan, termasuk alamat IP, karakteristik browser dan perangkat, timestamp, halaman yang dikunjungi, host rujukan, dan informasi diagnostik yang dapat dihasilkan oleh website atau infrastrukturnya.',
      'Informasi campaign dan attribution seperti UTM parameter dan identifier serupa ketika analytics opsional aktif setelah consent.',
      'Informasi lain yang Anda berikan secara sukarela melalui interaksi dengan Kapitech.'
    ]},
    { title: 'Informasi yang sebaiknya tidak dikirim', body: 'Formulir publik kami bukan saluran aman untuk mengirim informasi yang sangat sensitif kecuali formulir atau perjanjian tertulis terkait memang memintanya. Jangan kirim password, private encryption key, credential rekening, rahasia negara, rekam medis, atau informasi sensitif lain yang tidak diperlukan untuk permintaan Anda.\n\nJika informasi sensitif memang dibutuhkan untuk proyek yang telah dikontrak, gunakan metode atau proses transfer aman yang disepakati dengan tim Kapitech. Kami dapat menolak pemrosesan data yang berlebihan, tidak relevan dengan tujuan, atau menimbulkan risiko keamanan atau hukum yang tidak wajar.' },
    { title: 'Bagaimana kami memperoleh Data Pribadi', paragraphs: [
      'Langsung dari Anda saat mengisi formulir website, mengirim email, menghubungi kami melalui telepon atau WhatsApp, berlangganan informasi, atau berkomunikasi dengan tim kami.',
      'Dari browser atau perangkat Anda ketika informasi teknis yang diperlukan dihasilkan saat website digunakan.',
      'Dari informasi profesional atau publik yang Anda pilih untuk tersedia, seperti portfolio, website perusahaan, atau profil profesional dalam lamaran.',
      'Dari service provider yang menjalankan infrastruktur, komunikasi, pengiriman formulir, analytics, keamanan, hosting, atau sistem bisnis lain yang digunakan Kapitech.',
      'Dari klien atau perwakilan yang berwenang yang menyerahkan Data Pribadi kepada kami untuk tujuan berdasarkan kontrak.'
    ]},
    { title: 'Tujuan pemrosesan', body: 'Kami menggunakan Data Pribadi untuk tujuan bisnis, operasional, keamanan, dan komunikasi yang jelas. Data yang sama dapat mendukung beberapa tujuan yang saling berkaitan, tetapi kami tidak bermaksud mengumpulkan data sekadar “untuk berjaga-jaga”. Tujuan umum meliputi:', paragraphs: [
      'Menjawab pertanyaan, permintaan konsultasi, proposal, dan komunikasi bisnis.',
      'Memahami kebutuhan proyek dan menyiapkan scope, estimasi, jadwal, spesifikasi, dan materi pra-kontrak.',
      'Menjalankan layanan yang dikontrak, mengelola komunikasi, administrasi proyek, approval, invoice, dan catatan.',
      'Menilai lamaran kerja, internship, freelance, atau vendor dan berkomunikasi dengan kandidat atau partner.',
      'Mengirim newsletter, update, atau komunikasi lain yang diminta setelah Anda berlangganan atau memberikan izin yang sesuai.',
      'Mengoperasikan, menjaga, mengamankan, memonitor, memperbaiki masalah, dan meningkatkan website serta infrastrukturnya.',
      'Memahami penggunaan website dan performa campaign melalui analytics serta attribution opsional setelah consent.',
      'Mendeteksi fraud, abuse, aktivitas berbahaya, insiden keamanan, atau pelanggaran terhadap ketentuan kami.',
      'Memenuhi kewajiban hukum, regulasi, akuntansi, pajak, penyelesaian sengketa, atau kewajiban pencatatan.'
    ]},
    { title: 'Dasar pemrosesan', body: 'Kapitech berupaya memastikan setiap aktivitas pemrosesan memiliki dasar yang sah sesuai hukum yang berlaku. Tergantung konteksnya, dasar dapat berupa persetujuan yang sah; kebutuhan mengambil langkah atas permintaan seseorang sebelum kontrak; pelaksanaan kontrak; kewajiban hukum; perlindungan kepentingan vital; pelaksanaan fungsi untuk kepentingan umum atau pelayanan publik jika relevan; atau kepentingan sah setelah mempertimbangkan hak dan kepentingan subjek data.\n\nJika consent menjadi dasar, permintaan consent harus dijelaskan secara jelas untuk tujuan yang relevan dan tidak dianggap sebagai izin umum untuk tujuan yang tidak terkait. Penarikan consent tidak otomatis menghapus keabsahan pemrosesan yang telah dilakukan sebelum consent ditarik dan tidak menghalangi pemrosesan yang memiliki dasar hukum lain.' },
    { title: 'Formulir kontak dan permintaan bisnis', body: 'Data yang dikirim melalui formulir kontak digunakan terlebih dahulu untuk memahami dan menjawab permintaan. Ini dapat mencakup meninjau layanan yang diminta, meminta klarifikasi kebutuhan bisnis, meneruskan inquiry kepada anggota tim yang relevan, menyiapkan proposal, dan menyimpan catatan komunikasi.\n\nMengirim formulir kontak tidak otomatis berarti Anda berlangganan newsletter atau daftar marketing umum. Untuk komunikasi marketing berulang, digunakan subscription atau izin yang sesuai. Kami tetap dapat menghubungi Anda terkait inquiry atau proyek aktif tanpa menganggap komunikasi operasional tersebut sebagai marketing.' },
    { title: 'Informasi discovery dan pra-kontrak', body: 'Sebelum kontrak ditandatangani, kami dapat menerima informasi bisnis seperti rencana produk, target audience, kendala teknis, fungsi yang diinginkan, sistem yang sudah ada, ekspektasi anggaran, timeline, dan kebutuhan pengambilan keputusan internal. Informasi tersebut digunakan untuk menilai kesesuaian Kapitech dan menyiapkan materi yang relevan secara komersial.\n\nInformasi pra-kontrak dapat bersifat sensitif meskipun tidak selalu termasuk kategori Data Pribadi sensitif. Karena itu, kami berupaya membatasi akses internal kepada orang yang memang membutuhkan informasi tersebut untuk kegiatan sales, discovery, design, engineering, finance, atau management terkait.' },
    { title: 'Penjadwalan konsultasi, project brief, dan permintaan NDA', body: 'Alur konsultasi dapat mengumpulkan tanggal pilihan, waktu pilihan, timezone, industri, layanan yang diminati, detail proyek, serta permintaan NDA atau confidential handling sebelum informasi detail dipertukarkan. Data tersebut digunakan untuk qualification, memahami kebutuhan timing, meneruskan inquiry ke tim yang sesuai, dan menentukan langkah berikutnya. Waktu yang dipilih melalui website merupakan permintaan jadwal dan bukan booking otomatis kecuali ada mekanisme booking terpisah yang sudah dikonfirmasi.\n\nAlur konsultasi juga dapat menerima lampiran project brief dalam format dokumen yang didukung. File diunggah melalui public AMS API dan private document-storage flow sebelum referensinya dikaitkan dengan inquiry. Lampiran sebaiknya hanya berisi informasi yang wajar dan diperlukan untuk mengevaluasi proyek. Jangan mengunggah password, private key, credential finansial, secret, atau informasi sensitif lain yang tidak relevan. Request NDA dicatat pada inquiry dan tidak dengan sendirinya membentuk NDA yang ditandatangani kecuali Kapitech dan pihak terkait menyelesaikan NDA atau confidentiality agreement tertulis yang berlaku.' },
    { title: 'Lamaran kerja, freelance, dan vendor', body: 'Lamaran dapat berisi riwayat profesional, hasil kerja, resume, portfolio, kontak, ekspektasi kompensasi, ketersediaan, dan informasi lain yang dibutuhkan untuk menilai kandidat atau partner. Anggota tim recruitment, project, operations, design, engineering, finance, atau management yang berwenang dapat meninjau data sesuai kebutuhan.\n\nKami dapat menyimpan informasi lamaran untuk peluang berikutnya jika diperbolehkan dan relevan, tetapi lamaran tidak berarti otomatis ada hubungan kerja atau vendor. Hindari mengirim Data Pribadi sensitif yang tidak diperlukan. Jika proses recruitment tertentu memiliki informasi privasi tambahan, instruksi tersebut berlaku untuk proses tersebut.' },
    { title: 'Newsletter dan komunikasi marketing', body: 'Jika Kapitech menyediakan newsletter, project insights, campaign update, atau komunikasi berkala lainnya, kami menggunakan informasi yang diperlukan untuk mengirimkan komunikasi dan mengelola preferensi subscription. Pesan marketing dapat memiliki cara untuk unsubscribe atau memperbarui preferensi.\n\nPermintaan unsubscribe seharusnya menghentikan komunikasi marketing terkait, tetapi kami dapat menyimpan catatan minimal untuk memastikan alamat yang telah opt-out tidak secara tidak sengaja didaftarkan kembali. Komunikasi operasional yang diperlukan untuk menjawab inquiry, mengelola kontrak, atau menyediakan layanan tidak otomatis berhenti hanya karena Anda berhenti menerima marketing.' },
    { title: 'Informasi teknis, keamanan, dan penggunaan', body: 'Saat website digunakan, informasi teknis dapat dihasilkan secara otomatis oleh browser, hosting, content delivery, sistem keamanan, atau aplikasi. Tergantung konfigurasi, data dapat mencakup alamat IP, browser, sistem operasi, karakteristik perangkat, timestamp, halaman yang diminta, host rujukan, status HTTP, dan event diagnostik.\n\nInformasi ini terutama digunakan untuk delivery website, keamanan, reliability, troubleshooting, pencegahan abuse, analisis agregat, dan peningkatan layanan. Technical logs dapat dikelola terpisah dari marketing analytics dan tetap diperlukan walaupun consent analytics opsional tidak diberikan.' },
    { title: 'Cookie, local storage, dan consent', body: 'Kapitech menggunakan browser storage dan cookie sesuai Cookie Policy. Storage esensial dapat menyimpan pilihan bahasa atau consent agar website berfungsi secara konsisten. Analytics dan attribution opsional dimaksudkan hanya berjalan setelah pilihan consent yang mengizinkannya tercatat.\n\nStorage yang saat ini dikelola website mencakup nilai seperti “kapitech_cookie_consent”, “kapitech_lang”, “kapitech_attribution_v1”, dan “kapitech_anonymous_id_v1”. Key, provider, dan detail implementasi dapat berubah saat website berkembang. Cookie Policy menjadi dokumen yang lebih spesifik untuk perilaku cookie dan storage.' },
    { title: 'Analytics dan attribution', body: 'Jika consent analytics opsional aktif, website dapat menggunakan infrastruktur seperti Google Analytics 4 dan/atau Google Tag Manager yang dikonfigurasi. Tergantung konfigurasi, event dapat mencakup page view, interaksi tertentu, page path, bahasa, parameter campaign, dan informasi referral. Tujuannya adalah memahami penggunaan website dan performa campaign, bukan menjadikan website publik sebagai layanan broker data komersial.\n\nPemrosesan oleh provider juga mengikuti konfigurasi teknis dan ketentuan provider yang berlaku. Karena itu, kami tidak menjanjikan nama cookie, masa simpan, negara pemrosesan, atau fitur provider tertentu akan selalu sama.' },
    { title: 'Service provider dan processor', body: 'Kapitech dapat menggunakan provider pihak ketiga untuk hosting, database, file storage, email, form processing, CRM atau inbox, analytics, monitoring, security, domain, communications, payment infrastructure, development operations, atau fungsi bisnis lainnya. Tergantung layanannya, provider dapat memproses Data Pribadi atas nama kami atau bertindak sebagai penyedia independen dengan ketentuannya sendiri.\n\nKami berupaya memilih provider yang sesuai untuk layanan terkait, membatasi akses jika memungkinkan, serta menerapkan kontrol kontraktual atau teknis yang sesuai dengan sifat pemrosesan. Daftar provider dapat berubah seiring perubahan kebutuhan teknologi dan bisnis.' },
    { title: 'Pengungkapan kepada pihak lain', body: 'Kami dapat mengungkapkan Data Pribadi jika diperlukan untuk menjalankan bisnis, memenuhi permintaan, melaksanakan kontrak, mematuhi hukum, atau melindungi hak dan sistem yang sah. Contohnya dapat mencakup anggota tim dan kontraktor berwenang, infrastructure provider, penasihat profesional, auditor, provider pembayaran atau keuangan, otoritas hukum, atau pihak dalam transaksi korporasi yang sah.\n\nKami tidak bermaksud mengungkapkan informasi lebih banyak dari yang wajar diperlukan untuk tujuan terkait. Data Pribadi yang dikirim melalui website tidak dianggap sebagai informasi publik hanya karena pernah dikirim melalui website.' },
    { title: 'Permintaan hukum dan perlindungan hak', body: 'Dalam keadaan tertentu, Kapitech harus mengungkapkan informasi untuk memenuhi subpoena, perintah pengadilan, permintaan pemerintah yang sah, kewajiban regulator, atau proses hukum lain. Kami juga dapat mengungkapkan informasi jika secara wajar diperlukan untuk melindungi keamanan, hak, properti, atau keselamatan Kapitech, klien, pengguna, anggota tim, atau pihak lain, dengan tetap tunduk pada hukum yang berlaku.\n\nJika secara hukum diperbolehkan, kami berupaya membatasi pengungkapan pada informasi yang relevan dan menjaga kerahasiaan informasi yang tidak perlu diungkap.' },
    { title: 'Kerahasiaan klien dan proyek', body: 'Informasi yang diterima dalam engagement klien dapat tunduk pada proposal, SOW, NDA, klausul kerahasiaan, data-processing agreement, security schedule, atau pembatasan tertulis lainnya. Kewajiban kontraktual tersebut dapat lebih spesifik atau lebih ketat daripada kebijakan website ini.\n\nKapitech tidak dengan sengaja mempublikasikan informasi klien yang rahasia hanya karena informasi tersebut tersedia secara internal. Nama klien, logo, screenshot, arsitektur teknis, metric proyek, rencana produk yang belum dipublikasikan, credential, dan informasi sensitif lain hanya boleh dipublikasikan jika ada dasar kontraktual, consent, atau dasar hukum lain yang sesuai.' },
    { title: 'Pemrosesan dan transfer lintas negara', body: 'Kapitech dan provider kami dapat menggunakan infrastruktur di luar Indonesia. Karena itu, Data Pribadi dapat diproses, disimpan, atau diakses di negara atau yurisdiksi lain yang memiliki aturan privasi berbeda.\n\nJika pemrosesan lintas negara relevan, kami berupaya menerapkan safeguard kontraktual, teknis, dan organisasional yang wajar serta mengikuti kewajiban yang berlaku. Lokasi pemrosesan dapat berubah ketika provider mengubah infrastruktur sehingga kebijakan ini tidak menjanjikan seluruh data akan selamanya berada di satu negara.' },
    { title: 'Retensi Data Pribadi', body: 'Tidak ada satu periode retensi yang berlaku untuk semua Data Pribadi. Kami mempertimbangkan tujuan awal, jenis dan sensitivitas informasi, durasi hubungan bisnis atau proses lamaran, kebutuhan hukum dan akuntansi, risiko sengketa, kebutuhan keamanan, serta kebutuhan operasional.\n\nKetika informasi tidak lagi diperlukan untuk tujuan yang sah, kami berupaya menghapus, menghancurkan, menganonimkan, mende-identifikasi, atau membuangnya secara aman, dengan tetap mempertimbangkan kewajiban retensi hukum, backup, audit, atau kebutuhan sah lain yang membutuhkan penyimpanan terkontrol.' },
    { title: 'Akurasi dan minimisasi data', body: 'Kami berupaya menjaga Data Pribadi tetap akurat dan relevan dengan tujuan pemrosesan. Anda dapat membantu dengan memberikan informasi yang terbaru dan memberi tahu kami jika detail penting berubah. Kami dapat meminta klarifikasi jika data yang dikirim tampak tidak lengkap, tidak konsisten, atau dibutuhkan untuk menjalankan permintaan.\n\nKami juga berupaya menghindari pengumpulan informasi yang tidak relevan. Jika sebuah field bersifat opsional, umumnya Anda dapat mengosongkannya kecuali field tersebut memang diperlukan untuk menilai atau menjalankan permintaan.' },
    { title: 'Keamanan Data', body: 'Kami menggunakan kontrol teknis dan organisasional yang wajar sesuai sistem dan jenis informasi yang diproses. Tergantung konteks, kontrol dapat mencakup koneksi jaringan terenkripsi, autentikasi, pembatasan akses berdasarkan peran, pembatasan hak administratif, pengelolaan credential yang aman, logging, monitoring, backup, update software, dan pembatasan akses internal.\n\nKeamanan adalah proses, bukan jaminan mutlak. Tidak ada transmisi internet, software, cloud platform, perangkat, atau metode penyimpanan yang dapat dijamin sepenuhnya aman. Pengguna sebaiknya tidak mengirim secret atau credential melalui formulir website biasa.' },
    { title: 'Insiden Data Pribadi', body: 'Jika Kapitech mengetahui adanya dugaan atau insiden Data Pribadi yang terkonfirmasi, kami dapat menilai cakupan, sistem terdampak, kategori data, risiko yang mungkin muncul, opsi containment, dan kewajiban notifikasi berdasarkan hukum atau kontrak. Langkah respons dapat mencakup pembatasan akses, pemeriksaan log, pengamanan akun, perubahan konfigurasi, pemulihan sistem, komunikasi kepada pihak terdampak, dan dokumentasi perbaikan.\n\nJika notifikasi diwajibkan hukum, kami mengikuti ketentuan yang berlaku. Insiden keamanan tidak otomatis berarti semua pengguna terdampak, sehingga pemberitahuan sebaiknya didasarkan pada fakta yang telah diverifikasi selama proses respons.' },
    { title: 'Hak Anda atas Data Pribadi', body: 'Tunduk pada hukum yang berlaku, Anda dapat memiliki hak terkait Data Pribadi, termasuk memperoleh informasi yang jelas tentang pemrosesan, mengakses data, menerima salinan jika diwajibkan, memperbaiki atau memperbarui data yang tidak akurat, meminta penghapusan atau pemusnahan jika diperbolehkan, menarik consent ketika consent menjadi dasar pemrosesan, meminta penghentian atau pembatasan pemrosesan dalam keadaan tertentu, menolak pemrosesan atau profiling tertentu, dan menggunakan hak lain yang tersedia dalam kerangka hukum terkait.\n\nRuang lingkup setiap hak dapat bergantung pada dasar hukum, tujuan, pengecualian, kewajiban pihak ketiga, dan keadaan lainnya. Kebijakan ini tidak dimaksudkan untuk memperluas hak di luar yang diberikan hukum yang berlaku.' },
    { title: 'Cara menggunakan hak Anda', body: 'Kirim permintaan privasi atau permintaan hak Data Pribadi ke hello@kapitech.id. Jelaskan nama, kontak, jenis permintaan, dan konteks yang cukup agar kami dapat menemukan data terkait. Jika permintaan berkaitan dengan formulir, proyek, lamaran, atau komunikasi tertentu, sebutkan detail tersebut jika memungkinkan.\n\nKami dapat meminta informasi yang wajar untuk memverifikasi identitas sebelum mengakses, mengubah, atau menghapus data. Tujuannya untuk mengurangi risiko Data Pribadi diberikan kepada orang yang salah. Kami akan menangani permintaan dalam jangka waktu dan kondisi yang dipersyaratkan hukum. Jika permintaan tidak dapat dipenuhi seluruhnya, kami akan menjelaskan batasannya sejauh diperbolehkan.' },
    { title: 'Automated decision-making dan profiling', body: 'Website publik tidak dirancang untuk membuat keputusan berdampak tinggi tentang seseorang hanya berdasarkan automated processing. Analytics atau attribution dapat menghasilkan pengelompokan statistik atau pengukuran perilaku, tetapi fungsi tersebut tidak dimaksudkan untuk menentukan status hukum, kelayakan kerja, creditworthiness, atau akses terhadap layanan esensial seseorang.\n\nJika sistem di masa depan memperkenalkan automated decision-making atau profiling yang secara material berbeda, Kapitech akan menilai kebutuhan hukum, transparansi, keamanan, dan governance sebelum sistem tersebut digunakan untuk tujuan tersebut.' },
    { title: 'Anak-anak', body: 'Kapitech adalah digital agency profesional dan website ditujukan terutama bagi bisnis, profesional, klien, kandidat, vendor, dan pengguna dewasa lainnya. Kami tidak sengaja meminta Data Pribadi anak yang tidak diperlukan melalui formulir website biasa.\n\nJika orang tua, wali, atau pihak lain mengetahui bahwa anak telah mengirimkan Data Pribadi kepada Kapitech dalam keadaan yang seharusnya tidak terjadi, hubungi hello@kapitech.id dengan informasi terkait agar kami dapat menilai situasinya dan mengambil tindakan yang wajar sesuai hukum.' },
    { title: 'Website dan layanan pihak ketiga', body: 'Website dapat mengandung tautan ke website pihak ketiga, social network, hosted tools, embedded services, atau platform eksternal. Layanan tersebut dapat memiliki kebijakan privasi, penggunaan cookie, kontrol keamanan, dan ketentuan yang berbeda. Ketika Anda mengklik atau mengirim informasi pada layanan pihak ketiga, pemrosesan dapat berada di luar kendali langsung Kapitech.\n\nKami menyarankan Anda membaca privacy notice pihak ketiga sebelum mengirim informasi pribadi atau rahasia. Tautan dari kapitech.id tidak berarti Kapitech mengendalikan atau menjamin praktik pihak ketiga tersebut.' },
    { title: 'Perubahan, tanggal berlaku, dan kontak', body: 'Kami dapat memperbarui Kebijakan Privasi ketika website, operasional bisnis, teknologi, aktivitas pemrosesan, provider, atau kebutuhan hukum berubah. Versi terbaru akan dipublikasikan di halaman ini dengan tanggal berlaku yang diperbarui. Jika perubahan material membutuhkan pemberitahuan tambahan berdasarkan hukum atau kontrak, kami akan menggunakan cara pemberitahuan yang wajar.\n\nPT Kapitech Digital Indonesia\nLinea Residence, Blok G No. 5, Jl. Melati Loka, Paku Jaya, Serpong Utara, Kota Tangerang Selatan, Banten 15220, Indonesia\nEmail: hello@kapitech.id\nPhone / WhatsApp: +62 877-6995-7062' },
    { title: 'Kerangka hukum yang berlaku', body: 'Kebijakan ini dimaksudkan untuk dibaca bersama ketentuan Indonesia yang berlaku mengenai Data Pribadi dan sistem elektronik, termasuk Undang-Undang Republik Indonesia Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi dan Peraturan Pemerintah Nomor 71 Tahun 2019 tentang Penyelenggaraan Sistem dan Transaksi Elektronik, sepanjang berlaku dan sebagaimana dapat diubah, dilengkapi, atau digantikan dari waktu ke waktu.\n\nKebijakan ini merupakan pemberitahuan privasi untuk website publik dan bukan pengganti data-processing agreement, security schedule, NDA, kebijakan ketenagakerjaan, atau kontrak lain jika pengaturan yang lebih spesifik berlaku. Isi halaman ini juga bukan nasihat hukum.' }
  ]
};



const supplemental: Record<'en' | 'id', PolicySection[]> = {
  en: [
    { title: 'Data inventory by website interaction', body: 'Different website interactions can create different records. A contact enquiry can contain identity, business, and project information. A job application can contain professional history, portfolio links, resumes, and availability. A vendor or freelance submission can contain commercial and capability information. Newsletter activity can contain subscription and delivery status. Technical logs and consent records can exist separately from the contents of those submissions.\n\nThe fact that a person provides information for one interaction does not mean that every category is automatically used for every other purpose. We aim to connect information only where there is a relevant business, legal, security, or operational reason and where the applicable legal basis permits that use.' },
    { title: 'Processing by form and communication channel', paragraphs: [
      'Website forms are used for the purpose stated by the form and the related business workflow.',
      'Email communications are retained as business correspondence where necessary to understand a request, maintain continuity, document decisions, or resolve a dispute.',
      'Phone or WhatsApp communications may be recorded in internal business notes when needed to follow up on an enquiry or project, but users should not treat ordinary chat as a secure document-transfer channel.',
      'Attachments should contain only information reasonably necessary for the request. We may ask for a safer transfer method where the material is unusually sensitive or large.',
      'Newsletter subscription information is used to manage delivery and preference status and is not automatically treated as project data.'
    ]},
    { title: 'Access controls and internal handling', body: 'Access to Personal Data should be limited according to the work a person needs to perform. For example, a recruitment team member may need access to candidate information while a designer working on an unrelated client project may not. Finance personnel may need invoice or payment records but not the full contents of a candidate portfolio.\n\nWe use organisational practices and technical controls appropriate to the systems involved to reduce unnecessary access. Internal access can change as roles change, projects close, or a person no longer needs the information. Where information is stored with a service provider, provider-side access is governed by that provider’s controls and the applicable service arrangement.' },
    { title: 'Data quality, correction, and context', body: 'A piece of Personal Data can become inaccurate because a person changes jobs, contact details, company affiliation, professional experience, or other circumstances. We may correct information when a person asks us to do so or when an authorised business process identifies an error.\n\nCorrection does not necessarily require deletion of every historical reference to the previous value. For example, an invoice, contract, project note, or audit record may need to preserve its historical context. In those cases, the current information can be corrected while lawful records are retained as evidence of the earlier transaction.' },
    { title: 'Data minimisation in project discovery', body: 'Discovery conversations can produce more information than is ultimately necessary for a proposal. We seek to keep information that is useful for evaluating the request, preparing the scope, understanding constraints, and communicating with the relevant decision-makers.\n\nClients and prospective clients should avoid sending full production databases, user exports, password lists, private keys, or unrelated employee records merely to explain a project. Where sample or anonymised data is sufficient, using the smaller data set can reduce unnecessary exposure.' },
    { title: 'Retention examples and deletion lifecycle', body: 'Retention depends on the category of record. A completed enquiry may be retained as business correspondence for a reasonable period. Contract, invoice, tax, and accounting records may need longer retention to satisfy legal or financial requirements. Recruitment records may be retained for the current hiring process and, where appropriate, future opportunities. Security logs may be retained for a shorter or longer period depending on their operational role.\n\nWhen a retention period ends, deletion may happen in stages because active systems, backups, archives, or provider systems can have different deletion schedules. Secure deletion therefore means following the relevant system process rather than promising that every copy disappears at the exact same moment.' },
    { title: 'Incident response and notification assessment', body: 'When a possible Personal Data incident is identified, the relevant team may first secure the affected system, preserve evidence, establish what happened, identify the categories of information involved, and determine which individuals or systems may be affected. The incident can then be assessed for legal, contractual, operational, and security impact.\n\nNot every technical incident is a Personal Data breach, and not every breach affects every person whose information exists in the affected system. Any notification decision should therefore be based on the incident facts and the requirements that apply to the relevant data and parties.' },
    { title: 'Rights requests involving another person’s data', body: 'A request to access, correct, or delete information does not automatically authorise disclosure of someone else’s Personal Data. If a request involves shared records, another employee, a client contact, a candidate, or other third party, we may need to separate the requester’s data from information that cannot lawfully be disclosed.\n\nWe may also ask for evidence of authority where someone is acting on behalf of another person or organisation. The goal is to fulfil valid rights requests while preventing an unintended disclosure to an unauthorised requester.' },
    { title: 'Cross-border processing safeguards', body: 'Where a provider or project requires access from outside Indonesia, relevant safeguards may include contractual confidentiality, access restrictions, secure transfer mechanisms, provider security controls, authentication, and documented responsibilities. The exact safeguard depends on the data, provider, jurisdiction, service architecture, and legal requirements that apply.\n\nBecause service providers can use distributed infrastructure, “international transfer” may include remote access to a system even when the business relationship is established in Indonesia. We therefore consider both storage location and access location when assessing cross-border processing.' },
    { title: 'Accountability and records of processing decisions', body: 'Privacy governance also involves knowing why information is being processed, who needs access, how long it should be kept, and which provider handles it. For material processing activities, Kapitech may maintain internal records, contracts, configuration information, access controls, or operational notes that support those decisions.\n\nThese internal records are not necessarily public documents and may contain security-sensitive or commercially confidential information. They support accountability and operational control rather than serving as a public directory of every system detail.' },
    { title: 'Privacy questions and escalation', body: 'If you believe a request has been mishandled, a privacy statement is unclear, or information is being used outside the purpose you reasonably expected, contact hello@kapitech.id and describe the issue. Providing the relevant form, project, communication, or record can help us locate the correct information more quickly.\n\nWhere a matter involves a client contract, employee relationship, vendor agreement, or other specialised arrangement, the relevant contractual or internal policy may provide an additional escalation route. This public policy remains the baseline for the public website unless a more specific arrangement applies.' }
  ],
  id: [
    { title: 'Inventarisasi data berdasarkan interaksi website', body: 'Setiap interaksi website dapat menghasilkan jenis record yang berbeda. Inquiry kontak dapat berisi identitas, informasi bisnis, dan kebutuhan proyek. Lamaran kerja dapat berisi riwayat profesional, portfolio, resume, dan ketersediaan. Pengiriman vendor atau freelance dapat berisi informasi kemampuan dan komersial. Aktivitas newsletter dapat berisi status subscription dan delivery. Technical log dan consent record dapat tersimpan terpisah dari isi pengiriman tersebut.\n\nPemberian data untuk satu interaksi tidak berarti seluruh kategori data otomatis digunakan untuk semua tujuan lain. Kami berupaya menghubungkan informasi hanya jika ada alasan bisnis, hukum, keamanan, atau operasional yang relevan dan dasar pemrosesan yang mengizinkan.' },
    { title: 'Pemrosesan berdasarkan formulir dan channel komunikasi', paragraphs: [
      'Formulir website digunakan untuk tujuan yang dijelaskan pada formulir dan workflow bisnis terkait.',
      'Komunikasi email dapat disimpan sebagai korespondensi bisnis jika diperlukan untuk memahami inquiry, menjaga continuity, mendokumentasikan keputusan, atau menyelesaikan sengketa.',
      'Komunikasi telepon atau WhatsApp dapat dicatat dalam business notes ketika diperlukan untuk follow-up, tetapi chat biasa bukan saluran transfer dokumen yang aman.',
      'Lampiran sebaiknya hanya berisi informasi yang diperlukan. Kami dapat meminta metode transfer yang lebih aman untuk material yang sangat sensitif atau besar.',
      'Informasi subscription newsletter digunakan untuk delivery dan status preference dan tidak otomatis diperlakukan sebagai data proyek.'
    ]},
    { title: 'Access control dan penanganan internal', body: 'Akses Data Pribadi sebaiknya diberikan sesuai kebutuhan pekerjaan. Anggota recruitment membutuhkan akses pada informasi kandidat, sedangkan designer yang tidak mengerjakan proses tersebut tidak perlu melihatnya. Tim finance dapat membutuhkan invoice atau payment record tetapi tidak harus mengakses isi lengkap portfolio kandidat.\n\nKami menggunakan praktik organisasi dan kontrol teknis yang sesuai untuk mengurangi akses yang tidak diperlukan. Akses internal dapat berubah ketika role berubah, proyek selesai, atau seseorang tidak lagi membutuhkan data. Jika data berada pada provider, akses provider tunduk pada kontrol provider dan pengaturan layanan yang berlaku.' },
    { title: 'Kualitas data, koreksi, dan konteks', body: 'Data Pribadi dapat menjadi tidak akurat karena perubahan pekerjaan, kontak, perusahaan, pengalaman profesional, atau keadaan lainnya. Kami dapat memperbaiki data ketika diminta atau ketika proses bisnis yang berwenang menemukan kesalahan.\n\nKoreksi tidak selalu berarti semua catatan historis tentang nilai lama harus dihapus. Invoice, kontrak, catatan proyek, atau audit record mungkin perlu mempertahankan konteks historis. Dalam kondisi tersebut, informasi saat ini dapat diperbaiki sementara catatan yang sah tetap disimpan sebagai bukti transaksi.' },
    { title: 'Minimisasi data dalam project discovery', body: 'Diskusi discovery dapat menghasilkan informasi lebih banyak daripada yang akhirnya diperlukan untuk proposal. Kami berupaya menyimpan informasi yang benar-benar berguna untuk menilai permintaan, menyiapkan scope, memahami constraint, dan berkomunikasi dengan pengambil keputusan.\n\nKlien dan calon klien sebaiknya tidak mengirim database production lengkap, user export, password list, private key, atau data karyawan yang tidak terkait hanya untuk menjelaskan proyek. Jika sample atau data yang sudah dianonimkan cukup, penggunaan data yang lebih kecil akan mengurangi exposure yang tidak perlu.' },
    { title: 'Contoh retensi dan siklus penghapusan', body: 'Retensi bergantung pada kategori record. Inquiry yang sudah selesai dapat disimpan sebagai korespondensi bisnis untuk periode yang wajar. Contract, invoice, pajak, dan accounting record dapat membutuhkan retensi lebih lama untuk memenuhi kewajiban hukum atau keuangan. Data recruitment dapat disimpan selama proses hiring dan, bila sesuai, untuk peluang berikutnya. Security log dapat disimpan sesuai kebutuhan operasionalnya.\n\nKetika periode retensi berakhir, penghapusan dapat berlangsung bertahap karena active system, backup, archive, dan provider memiliki siklus yang berbeda. Secure deletion berarti mengikuti proses sistem yang sesuai, bukan menjanjikan bahwa setiap salinan hilang pada detik yang sama.' },
    { title: 'Incident response dan penilaian notifikasi', body: 'Ketika ada dugaan insiden Data Pribadi, tim terkait dapat mengamankan sistem, mempertahankan evidence, mencari tahu kejadian, mengidentifikasi kategori data, dan menilai individu atau sistem yang mungkin terdampak. Setelah itu dapat dilakukan penilaian terhadap dampak hukum, kontraktual, operasional, dan security.\n\nTidak setiap technical incident merupakan breach Data Pribadi dan tidak setiap breach memengaruhi semua orang yang datanya berada dalam sistem. Karena itu, keputusan notifikasi harus berdasarkan fakta insiden dan kewajiban yang berlaku.' },
    { title: 'Permintaan hak yang mencakup data orang lain', body: 'Permintaan untuk mengakses, memperbaiki, atau menghapus data tidak otomatis memberi izin untuk membuka Data Pribadi orang lain. Jika request menyangkut shared record, employee, client contact, candidate, atau pihak ketiga lain, kami dapat perlu memisahkan data pemohon dari data yang tidak boleh diungkapkan.\n\nKami juga dapat meminta bukti kewenangan jika seseorang bertindak atas nama orang atau organisasi lain. Tujuannya adalah memenuhi request yang sah tanpa membuat disclosure kepada pihak yang tidak berwenang.' },
    { title: 'Safeguard untuk pemrosesan lintas negara', body: 'Jika provider atau proyek membutuhkan akses dari luar Indonesia, safeguard dapat mencakup confidentiality contract, access restriction, secure transfer mechanism, provider security controls, authentication, dan pembagian tanggung jawab yang terdokumentasi. Safeguard tepat bergantung pada data, provider, yurisdiksi, arsitektur layanan, dan hukum yang berlaku.\n\nKarena provider dapat menggunakan infrastruktur terdistribusi, transfer lintas negara dapat mencakup remote access meskipun hubungan bisnisnya berada di Indonesia. Karena itu kami mempertimbangkan lokasi penyimpanan sekaligus lokasi akses.' },
    { title: 'Akuntabilitas dan catatan keputusan pemrosesan', body: 'Governance privasi juga berarti memahami mengapa data diproses, siapa yang membutuhkan akses, berapa lama data disimpan, dan provider mana yang menanganinya. Untuk aktivitas material, Kapitech dapat memiliki internal record, contract, configuration record, access control, atau operational note yang mendukung keputusan tersebut.\n\nRecord internal tidak selalu merupakan dokumen publik dan dapat berisi security-sensitive atau confidential business information. Record tersebut digunakan untuk accountability dan operational control, bukan sebagai daftar publik seluruh detail sistem.' },
    { title: 'Pertanyaan privasi dan eskalasi', body: 'Jika Anda merasa suatu request tidak ditangani dengan benar, kebijakan tidak jelas, atau data digunakan di luar tujuan yang Anda pahami secara wajar, hubungi hello@kapitech.id dan jelaskan masalahnya. Menyebutkan formulir, proyek, komunikasi, atau record terkait dapat membantu kami menemukan informasi dengan lebih cepat.\n\nJika masalah berkaitan dengan client contract, employment, vendor agreement, atau pengaturan khusus lain, kontrak atau policy terkait dapat menyediakan jalur eskalasi tambahan. Kebijakan publik ini tetap menjadi baseline untuk website publik kecuali pengaturan yang lebih spesifik berlaku.' }
  ]
};

export const PrivacyPolicy = () => {
  const { language } = useLanguage();
  const current = language === 'id' ? sections.id : sections.en;
  const extra = language === 'id' ? supplemental.id : supplemental.en;
  const ordered = [...current.slice(0, -2), ...extra, ...current.slice(-2)];
  return (
    <PolicyPageShell
      eyebrow={language === 'id' ? 'Privasi & Pelindungan Data' : 'Privacy & Data Protection'}
      title={language === 'id' ? 'Kebijakan Privasi.' : 'Privacy Policy.'}
      updated={language === 'id' ? 'Diperbarui: 8 Oktober 2026' : 'Updated: October 8, 2026'}
      summary={language === 'id'
        ? 'Kebijakan ini menjelaskan secara rinci bagaimana Kapitech menangani Data Pribadi pada website publik, formulir, komunikasi, recruitment, vendor intake, analytics, attribution, dan interaksi terkait, termasuk hak, safeguard, retensi, dan cara mengajukan request.'
        : 'This policy explains in detail how Kapitech handles Personal Data across the public website, forms, communications, recruitment, vendor intake, analytics, attribution, and related interactions, including rights, safeguards, retention, and how to make a request.'}
      sections={ordered}
    />
  );
};